size_t CowSwapOrder::Hash(size_t seed) const {
  seed = mojo::internal::Hash(seed, this->sell_token);
  seed = mojo::internal::Hash(seed, this->sell_amount);
  seed = mojo::internal::Hash(seed, this->buy_token);
  seed = mojo::internal::Hash(seed, this->buy_amount);
  seed = mojo::internal::Hash(seed, this->receiver);
  seed = mojo::internal::Hash(seed, this->deadline);
  return seed;
}

