void ProviderErrorUnion::DestroyActive() {
  switch (tag_) {

    case Tag::kProviderError:
      std::destroy_at(&data_.provider_error);
      break;
    case Tag::kSolanaProviderError:
      std::destroy_at(&data_.solana_provider_error);
      break;
    case Tag::kFilecoinProviderError:
      std::destroy_at(&data_.filecoin_provider_error);
      break;
    case Tag::kBitcoinProviderError:
      std::destroy_at(&data_.bitcoin_provider_error);
      break;
    case Tag::kZcashProviderError:
      std::destroy_at(&data_.zcash_provider_error);
      break;
    case Tag::kCardanoProviderError:
      std::destroy_at(&data_.cardano_provider_error);
      break;
    case Tag::kPolkadotProviderError:
      std::destroy_at(&data_.polkadot_provider_error);
      break;
  }
}
size_t ProviderErrorUnion::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kProviderError:
      return mojo::internal::Hash(seed, data_.provider_error);
    case Tag::kSolanaProviderError:
      return mojo::internal::Hash(seed, data_.solana_provider_error);
    case Tag::kFilecoinProviderError:
      return mojo::internal::Hash(seed, data_.filecoin_provider_error);
    case Tag::kBitcoinProviderError:
      return mojo::internal::Hash(seed, data_.bitcoin_provider_error);
    case Tag::kZcashProviderError:
      return mojo::internal::Hash(seed, data_.zcash_provider_error);
    case Tag::kCardanoProviderError:
      return mojo::internal::Hash(seed, data_.cardano_provider_error);
    case Tag::kPolkadotProviderError:
      return mojo::internal::Hash(seed, data_.polkadot_provider_error);
    default:
      NOTREACHED();
  }
}

bool ProviderErrorUnion::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
