size_t SwapErrorUnion::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kJupiterError:
      return mojo::internal::Hash(seed, data_.jupiter_error);
    case Tag::kZeroExError:
      return mojo::internal::Hash(seed, data_.zero_ex_error);
    case Tag::kGate3Error:
      return mojo::internal::Hash(seed, data_.gate3_error);
    default:
      NOTREACHED();
  }
}

