// static
bool SolanaEventsListenerStubDispatch::Accept(
    SolanaEventsListener* impl,
    mojo::Message* message) {
  switch (static_cast<messages::SolanaEventsListener>(message->header()->name)) {
    case messages::SolanaEventsListener::kAccountChangedEvent: {
      DCHECK(message->is_serialized());
      internal::SolanaEventsListener_AccountChangedEvent_Params_Data* params =
          reinterpret_cast<internal::SolanaEventsListener_AccountChangedEvent_Params_Data*>(
              message->mutable_payload());
      

      // Validation for SolanaEventsListener.0
      bool success = true;
      std::optional<std::string> p_account{};
      SolanaEventsListener_AccountChangedEvent_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadAccount(&p_account))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SolanaEventsListener::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->AccountChangedEvent(        
        std::move(p_account));
      return true;
    }
    case messages::SolanaEventsListener::kDisconnectEvent: {
      DCHECK(message->is_serialized());
      internal::SolanaEventsListener_DisconnectEvent_Params_Data* params =
          reinterpret_cast<internal::SolanaEventsListener_DisconnectEvent_Params_Data*>(
              message->mutable_payload());
      

      // Validation for SolanaEventsListener.1
      bool success = true;
      SolanaEventsListener_DisconnectEvent_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            SolanaEventsListener::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->DisconnectEvent(        );
      return true;
    }
  }
  return false;
}

