// The declaration includes the definition on other builds.

CardanoProvider::IPCStableHashFunction CardanoProvider::MessageToMethodInfo_(mojo::Message& message) {
#if !BUILDFLAG(IS_FUCHSIA)
  switch (static_cast<messages::CardanoProvider>(message.name())) {
    case messages::CardanoProvider::kEnable: {
      return &CardanoProvider::Enable_Sym::IPCStableHash;
    }
    case messages::CardanoProvider::kIsEnabled: {
      return &CardanoProvider::IsEnabled_Sym::IPCStableHash;
    }
  }
#endif  // !BUILDFLAG(IS_FUCHSIA)
  return nullptr;
}


const char* CardanoProvider::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::CardanoProvider>(message.name())) {
      case messages::CardanoProvider::kEnable:
            return "Receive brave_wallet::mojom::CardanoProvider::Enable";
      case messages::CardanoProvider::kIsEnabled:
            return "Receive brave_wallet::mojom::CardanoProvider::IsEnabled";
    }
  } else {
    switch (static_cast<messages::CardanoProvider>(message.name())) {
      case messages::CardanoProvider::kEnable:
            return "Receive reply brave_wallet::mojom::CardanoProvider::Enable";
      case messages::CardanoProvider::kIsEnabled:
            return "Receive reply brave_wallet::mojom::CardanoProvider::IsEnabled";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

