void PanelHandlerObserverProxy::OnActivePanelOriginChanged(
    OriginInfoPtr in_origin_info) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send brave_wallet::mojom::PanelHandlerObserver::OnActivePanelOriginChanged", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("origin_info"), in_origin_info,
                        "<value of type OriginInfoPtr>");
   });
#endif

  const bool kExpectsResponse = false;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::PanelHandlerObserver::kOnActivePanelOriginChanged), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::PanelHandlerObserver_OnActivePanelOriginChanged_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->origin_info)::BaseType> origin_info_fragment(
          params.message());
  
  mojo::internal::Serialize<::brave_wallet::mojom::OriginInfoDataView>(
    in_origin_info,
    origin_info_fragment);

  params->origin_info.Set(
      origin_info_fragment.is_null() ? nullptr : origin_info_fragment.data());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(params->origin_info.is_null()),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
    "null origin_info in PanelHandlerObserver.OnActivePanelOriginChanged request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(PanelHandlerObserver::Name_);
  message.set_method_name("OnActivePanelOriginChanged");
#endif
  // This return value may be ignored as false implies the Connector has
  // encountered an error, which will be visible through other means.
  ::mojo::internal::SendMojoMessage(*receiver_, message);
}

