class PanelHandler_GetActivePanelOrigin_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static PanelHandler::GetActivePanelOriginCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder) {
    std::unique_ptr<PanelHandler_GetActivePanelOrigin_ProxyToResponder> proxy(
        new PanelHandler_GetActivePanelOrigin_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&PanelHandler_GetActivePanelOrigin_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~PanelHandler_GetActivePanelOrigin_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  PanelHandler_GetActivePanelOrigin_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "PanelHandler::GetActivePanelOriginCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      OriginInfoPtr in_origin_info);
};

bool PanelHandler_GetActivePanelOrigin_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::PanelHandler_GetActivePanelOrigin_ResponseParams_Data* params =
      reinterpret_cast<
          internal::PanelHandler_GetActivePanelOrigin_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for PanelHandler.1
  bool success = true;
  OriginInfoPtr p_origin_info{};
  PanelHandler_GetActivePanelOrigin_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadOriginInfo(&p_origin_info))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        PanelHandler::Name_, 1, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_origin_info));
  }
  return true;
}

