const char* PageHandler::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::PageHandler>(message.name())) {
      case messages::PageHandler::kShowApprovePanelUI:
            return "Receive brave_wallet::mojom::PageHandler::ShowApprovePanelUI";
      case messages::PageHandler::kShowWalletBackupUI:
            return "Receive brave_wallet::mojom::PageHandler::ShowWalletBackupUI";
      case messages::PageHandler::kUnlockWalletUI:
            return "Receive brave_wallet::mojom::PageHandler::UnlockWalletUI";
      case messages::PageHandler::kShowOnboarding:
            return "Receive brave_wallet::mojom::PageHandler::ShowOnboarding";
      case messages::PageHandler::kOpenWalletHome:
            return "Receive brave_wallet::mojom::PageHandler::OpenWalletHome";
      case messages::PageHandler::kScanQRCode:
            return "Receive brave_wallet::mojom::PageHandler::ScanQRCode";
      case messages::PageHandler::kOpenTab:
            return "Receive brave_wallet::mojom::PageHandler::OpenTab";
    }
  } else {
    switch (static_cast<messages::PageHandler>(message.name())) {
      case messages::PageHandler::kShowApprovePanelUI:
            return "Receive reply brave_wallet::mojom::PageHandler::ShowApprovePanelUI";
      case messages::PageHandler::kShowWalletBackupUI:
            return "Receive reply brave_wallet::mojom::PageHandler::ShowWalletBackupUI";
      case messages::PageHandler::kUnlockWalletUI:
            return "Receive reply brave_wallet::mojom::PageHandler::UnlockWalletUI";
      case messages::PageHandler::kShowOnboarding:
            return "Receive reply brave_wallet::mojom::PageHandler::ShowOnboarding";
      case messages::PageHandler::kOpenWalletHome:
            return "Receive reply brave_wallet::mojom::PageHandler::OpenWalletHome";
      case messages::PageHandler::kScanQRCode:
            return "Receive reply brave_wallet::mojom::PageHandler::ScanQRCode";
      case messages::PageHandler::kOpenTab:
            return "Receive reply brave_wallet::mojom::PageHandler::OpenTab";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

