void BlockchainRegistry_GetCoingeckoId_ProxyToResponder::Run(
    const std::optional<std::string>& in_coingecko_id) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply brave_wallet::mojom::BlockchainRegistry::GetCoingeckoId", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("coingecko_id"), in_coingecko_id,
                        "<value of type const std::optional<std::string>&>");
   });
#endif

  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::BlockchainRegistry::kGetCoingeckoId), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::BlockchainRegistry_GetCoingeckoId_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->coingecko_id)::BaseType> coingecko_id_fragment(
          params.message());
  
  mojo::internal::Serialize<mojo::StringDataView>(
    in_coingecko_id,
    coingecko_id_fragment);

  params->coingecko_id.Set(
      coingecko_id_fragment.is_null() ? nullptr : coingecko_id_fragment.data());

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(BlockchainRegistry::Name_);
  message.set_method_name("GetCoingeckoId");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

