bool AssetRatioService_GetPrice_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::AssetRatioService_GetPrice_ResponseParams_Data* params =
      reinterpret_cast<
          internal::AssetRatioService_GetPrice_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for AssetRatioService.0
  bool success = true;
  bool p_success{};
  std::vector<AssetPricePtr> p_values{};
  AssetRatioService_GetPrice_ResponseParamsDataView input_data_view(params, message);
  
  if (success)
    p_success = input_data_view.success();
  if (success && !input_data_view.ReadValues(&p_values))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        AssetRatioService::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_success), 
std::move(p_values));
  }
  return true;
}

