class TxService_AddUnapprovedEvmTransaction_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static TxService::AddUnapprovedEvmTransactionCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder) {
    std::unique_ptr<TxService_AddUnapprovedEvmTransaction_ProxyToResponder> proxy(
        new TxService_AddUnapprovedEvmTransaction_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&TxService_AddUnapprovedEvmTransaction_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~TxService_AddUnapprovedEvmTransaction_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  TxService_AddUnapprovedEvmTransaction_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::internal::ResponderThunk>&& responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "TxService::AddUnapprovedEvmTransactionCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      bool in_success, const std::string& in_tx_meta_id, const std::string& in_error_message);
};

bool TxService_AddUnapprovedEvmTransaction_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::TxService_AddUnapprovedEvmTransaction_ResponseParams_Data* params =
      reinterpret_cast<
          internal::TxService_AddUnapprovedEvmTransaction_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for TxService.0
  bool success = true;
  bool p_success{};
  std::string p_tx_meta_id{};
  std::string p_error_message{};
  TxService_AddUnapprovedEvmTransaction_ResponseParamsDataView input_data_view(params, message);
  
  if (success)
    p_success = input_data_view.success();
  if (success && !input_data_view.ReadTxMetaId(&p_tx_meta_id))
    success = false;
  if (success && !input_data_view.ReadErrorMessage(&p_error_message))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        TxService::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_success), 
std::move(p_tx_meta_id), 
std::move(p_error_message));
  }
  return true;
}

