  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::TxService::kGetPendingTransactionsCount), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::TxService_GetPendingTransactionsCount_ResponseParams_Data> params(
          message);
  params.Allocate();

  params->count = in_count;

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(TxService::Name_);
  message.set_method_name("GetPendingTransactionsCount");
#endif

  message.set_request_id(request_id_);
