const char* SnapService::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::SnapService>(message.name())) {
      case messages::SnapService::kLoadSnap:
            return "Receive brave_wallet::mojom::SnapService::LoadSnap";
      case messages::SnapService::kBindSnapHostBridge:
            return "Receive brave_wallet::mojom::SnapService::BindSnapHostBridge";
    }
  } else {
    switch (static_cast<messages::SnapService>(message.name())) {
      case messages::SnapService::kLoadSnap:
            return "Receive reply brave_wallet::mojom::SnapService::LoadSnap";
      case messages::SnapService::kBindSnapHostBridge:
            return "Receive reply brave_wallet::mojom::SnapService::BindSnapHostBridge";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

