const char* SnapHostBridge::MessageToMethodName_(mojo::Message& message) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (!is_response) {
    switch (static_cast<messages::SnapHostBridge>(message.name())) {
      case messages::SnapHostBridge::kLoadSnap:
            return "Receive brave_wallet::mojom::SnapHostBridge::LoadSnap";
      case messages::SnapHostBridge::kUnloadSnap:
            return "Receive brave_wallet::mojom::SnapHostBridge::UnloadSnap";
    }
  } else {
    switch (static_cast<messages::SnapHostBridge>(message.name())) {
      case messages::SnapHostBridge::kLoadSnap:
            return "Receive reply brave_wallet::mojom::SnapHostBridge::LoadSnap";
      case messages::SnapHostBridge::kUnloadSnap:
            return "Receive reply brave_wallet::mojom::SnapHostBridge::UnloadSnap";
    }
  }
  return "Receive unknown mojo message";
#else
  bool is_response = message.has_flag(mojo::Message::kFlagIsResponse);
  if (is_response) {
    return "Receive mojo reply";
  } else {
    return "Receive mojo message";
  }
#endif // BUILDFLAG(MOJO_TRACE_ENABLED)
}

