void SnapHostBridgeProxy::LoadSnap(
    const std::string& in_snap_id, const std::string& in_source_code, LoadSnapCallback callback) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send brave_wallet::mojom::SnapHostBridge::LoadSnap", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("snap_id"), in_snap_id,
                        "<value of type const std::string&>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("source_code"), in_source_code,
                        "<value of type const std::string&>");
   });
#endif

  const bool kExpectsResponse = true;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;

  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::SnapHostBridge::kLoadSnap), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::brave_wallet::mojom::internal::SnapHostBridge_LoadSnap_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->snap_id)::BaseType> snap_id_fragment(
          params.message());
  
  mojo::internal::Serialize<mojo::StringDataView>(
    in_snap_id,
    snap_id_fragment);

  params->snap_id.Set(
      snap_id_fragment.is_null() ? nullptr : snap_id_fragment.data());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(params->snap_id.is_null()),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
    "null snap_id in SnapHostBridge.LoadSnap request");
  mojo::internal::MessageFragment<
      typename decltype(params->source_code)::BaseType> source_code_fragment(
          params.message());
  
  mojo::internal::Serialize<mojo::StringDataView>(
    in_source_code,
    source_code_fragment);

  params->source_code.Set(
      source_code_fragment.is_null() ? nullptr : source_code_fragment.data());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(params->source_code.is_null()),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
    "null source_code in SnapHostBridge.LoadSnap request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(SnapHostBridge::Name_);
  message.set_method_name("LoadSnap");
#endif
  std::unique_ptr<mojo::MessageReceiver> responder(
      new SnapHostBridge_LoadSnap_ForwardToCallback(
          std::move(callback)));
  ::mojo::internal::SendMojoMessage(*receiver_, message, std::move(responder));
}

