// static
bool StructTraits<::brave_wallet::mojom::EthereumProviderResponse::DataView, ::brave_wallet::mojom::EthereumProviderResponsePtr>::Read(
    ::brave_wallet::mojom::EthereumProviderResponse::DataView input,
    ::brave_wallet::mojom::EthereumProviderResponsePtr* output) {
  bool success = true;
  ::brave_wallet::mojom::EthereumProviderResponsePtr result(::brave_wallet::mojom::EthereumProviderResponse::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadFormedResponse(&result->formed_response))
        success = false;
      if (success)
        result->reject = input.reject();
      if (success && !input.ReadFirstAllowedAccount(&result->first_allowed_account))
        success = false;
      if (success)
        result->update_bind_js_properties = input.update_bind_js_properties();
  *output = std::move(result);
  return success;
}


