JsonRpcServiceAsyncWaiter::JsonRpcServiceAsyncWaiter(
    JsonRpcService* proxy) : proxy_(proxy) {}

JsonRpcServiceAsyncWaiter::~JsonRpcServiceAsyncWaiter() = default;


void JsonRpcServiceAsyncWaiter::AddChain(
    NetworkInfoPtr chain, std::string* out_chain_id, ProviderError* out_error, std::string* out_error_message) {
  base::RunLoop loop;
  proxy_->AddChain(
      std::move(chain),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_chain_id
,
             ProviderError* out_error
,
             std::string* out_error_message
,
             const std::string& chain_id,
             ProviderError error,
             const std::string& error_message) {*out_chain_id = std::move(chain_id);*out_error = std::move(error);*out_error_message = std::move(error_message);
            loop->Quit();
          },
          &loop,
          out_chain_id,
          out_error,
          out_error_message));
  loop.Run();
}



void JsonRpcServiceAsyncWaiter::RemoveChain(
    const std::string& chain_id, ::brave_wallet::mojom::CoinType coin, bool* out_success) {
  base::RunLoop loop;
  proxy_->RemoveChain(
      std::move(chain_id),
      std::move(coin),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool JsonRpcServiceAsyncWaiter::RemoveChain(
    const std::string& chain_id, ::brave_wallet::mojom::CoinType coin) {
  bool async_wait_result;
  RemoveChain(std::move(chain_id),std::move(coin),&async_wait_result);
  return async_wait_result;
}

