BraveWalletServiceAsyncWaiter::BraveWalletServiceAsyncWaiter(
    BraveWalletService* proxy) : proxy_(proxy) {}

BraveWalletServiceAsyncWaiter::~BraveWalletServiceAsyncWaiter() = default;


void BraveWalletServiceAsyncWaiter::GetAllUserAssets(
    std::vector<BlockchainTokenPtr>* out_tokens) {
  base::RunLoop loop;
  proxy_->GetAllUserAssets(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<BlockchainTokenPtr>* out_tokens
,
             std::vector<BlockchainTokenPtr> tokens) {*out_tokens = std::move(tokens);
            loop->Quit();
          },
          &loop,
          out_tokens));
  loop.Run();
}

std::vector<BlockchainTokenPtr> BraveWalletServiceAsyncWaiter::GetAllUserAssets(
    ) {
  std::vector<BlockchainTokenPtr> async_wait_result;
  GetAllUserAssets(&async_wait_result);
  return async_wait_result;
}

