void BraveWalletServiceAsyncWaiter::ImportFromExternalWallet(
    ExternalWalletType type, const std::string& password, const std::string& newPassword, bool* out_success, std::optional<std::string>* out_errorMessage) {
  base::RunLoop loop;
  proxy_->ImportFromExternalWallet(
      std::move(type),
      std::move(password),
      std::move(newPassword),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             std::optional<std::string>* out_errorMessage
,
             bool success,
             const std::optional<std::string>& errorMessage) {*out_success = std::move(success);*out_errorMessage = std::move(errorMessage);
            loop->Quit();
          },
          &loop,
          out_success,
          out_errorMessage));
  loop.Run();
}



